6: const MODEL = 'deepseek/deepseek-chat-v3-0324';
7: const API = 'https://openrouter.ai/api/v1';
8: const MAX_REQUESTS = 10;
9: const MAX_OUTPUT = 4096;
10: // Raised from 80,000 after a real run read every file and could not send the request: this
11: // repository's own experiment log had grown to 38,322 of 78,755 serialized tool bytes. The
12: // bound exists to cap cost, which this does not threaten; it defers the growth problem.
13: const MAX_CONTEXT_BYTES = 120_000;
