6: const exec = promisify(execFile);
7: // Large enough that every file in this repository arrives complete in one read.
8: const READ_BYTES = 40_000;
9: const parameters = properties => ({ type: 'object', properties, additionalProperties: false });
10: const string = description => ({ type: 'string', description });
11: const integer = description => ({ type: 'integer', description });
