13: export const tools = [
14:   ['list_files', 'List tracked repository files. Paginate with offset.', {
15:     offset: integer('Zero-based file offset; default 0'),
16:   }],
17:   ['read_file', 'Read a tracked text file with line numbers. Whole files are returned when they fit; only very large files need paginating with startLine.', {
18:     path: string('Exact repository-relative path'),
19:     startLine: integer('First line, starting at 1; default 1'),
20:   }],
21:   ['search', 'Search tracked text files for literal text; returns matching paths and lines.', {
22:     text: string('Nonempty literal search text'),
23:   }],
24:   ['history', 'Inspect the last ten commit subjects, optionally for one tracked file.', {
25:     path: string('Optional exact repository-relative path'),
26:   }],
27: ].map(([name, description, properties]) => ({
28:   type: 'function', function: { name, description, parameters: parameters(properties) },
29: }));
